<script lang="ts">let {data}=$props(); let s=$derived(data.snapshot); const money=(e:any)=>new Intl.NumberFormat('en-US',{style:'currency',currency:e.currency}).format(e.amount/100); let selected=$state<any>(null);</script>
<svelte:head><title>Transaction graph · DriftRecon</title></svelte:head><main class="shell workspace"><p class="eyebrow">Financial lineage</p><h1 class="title">Transaction graph</h1><p class="lede">Follow supported events through processor payout to the bank deposit. Select an event for its evidence and references.</p>{#if !s.events.length}<div class="card empty section">Import activity on Overview to build the graph.</div>{:else}<section class="card graph section"><div class="chain">{#each s.events.slice(0,5) as event,i}<button class="node" onclick={()=>selected=event}><span class="eyebrow">{event.source}</span><strong style="display:block;margin:12px 0 6px;text-transform:capitalize">{event.kind.replace('_',' ')}</strong><span class="mono">{money(event)}</span></button>{#if i<4}<span class="arrow">→</span>{/if}{/each}</div></section>{#if selected}<section class="card section"><header class="card-head"><strong>Event details</strong></header><div class="card-body grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))"><div><span class="eyebrow">Source</span><p>{selected.source}</p></div><div><span class="eyebrow">Type</span><p>{selected.kind}</p></div><div><span class="eyebrow">Amount</span><p>{money(selected)}</p></div><div><span class="eyebrow">Reference</span><p class="mono">{selected.externalRef||'Missing'}</p></div></div></section>{/if}{/if}</main>
